using LigaVolley.Domain.MatchOfficials;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace LigaVolley.Infrastructure.Persistence.Configurations;
internal sealed class MatchOfficialConfiguration:IEntityTypeConfiguration<MatchOfficial>{public void Configure(EntityTypeBuilder<MatchOfficial>b){b.ToTable("MATCH_OFFICIAL","dbo",t=>t.HasCheckConstraint("CK_MATCH_OFFICIAL_role","[role] IN ('FIRST_REFEREE','SECOND_REFEREE','SCORER')"));b.HasKey(x=>x.MatchOfficialId);b.Property(x=>x.MatchOfficialId).HasColumnName("match_official_id").UseIdentityColumn();b.Property(x=>x.MatchId).HasColumnName("match_id");b.Property(x=>x.RefereeId).HasColumnName("referee_id");b.Property(x=>x.Role).AsSql("role",20);b.HasOne(x=>x.Match).WithMany().HasForeignKey(x=>x.MatchId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Referee).WithMany().HasForeignKey(x=>x.RefereeId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchId,x.Role}).IsUnique().HasDatabaseName("UQ_MATCH_OFFICIAL_role");b.HasIndex(x=>new{x.MatchId,x.RefereeId}).IsUnique().HasDatabaseName("UQ_MATCH_OFFICIAL_referee");}}
